ALTER TABLE company_features DROP CONSTRAINT IF EXISTS ck_company_feature;
ALTER TABLE company_features ADD CONSTRAINT ck_company_feature CHECK (feature IN ('DASHBOARD','CLIENTS','PRODUCTS','PURCHASES','NEW_SALE','SALES','RECEIVABLES','ORDERS','ROUTES','REPORTS','CHARTS','SETTINGS','FIXED_EXPENSES','PROMOTIONS','COURIERS','SNACKS','NOTES'));
CREATE TABLE couriers (id UUID PRIMARY KEY, company_id UUID NOT NULL REFERENCES empresas(id) ON DELETE CASCADE, name VARCHAR(160) NOT NULL, phone VARCHAR(40), delivery_fee NUMERIC(14,2) NOT NULL DEFAULT 0); CREATE INDEX idx_couriers_company ON couriers(company_id);
CREATE TABLE snacks (id UUID PRIMARY KEY, company_id UUID NOT NULL REFERENCES empresas(id) ON DELETE CASCADE, name VARCHAR(160) NOT NULL, price NUMERIC(14,2) NOT NULL); CREATE INDEX idx_snacks_company ON snacks(company_id);
CREATE TABLE snack_ingredients (snack_id UUID NOT NULL REFERENCES snacks(id) ON DELETE CASCADE, ingredient VARCHAR(200) NOT NULL);
CREATE TABLE snack_additionals (snack_id UUID NOT NULL REFERENCES snacks(id) ON DELETE CASCADE, name VARCHAR(160) NOT NULL, price NUMERIC(14,2) NOT NULL);
CREATE TABLE snack_orders (id UUID PRIMARY KEY, company_id UUID NOT NULL REFERENCES empresas(id) ON DELETE CASCADE, courier_id UUID REFERENCES couriers(id) ON DELETE SET NULL, client_name VARCHAR(200) NOT NULL, client_phone VARCHAR(50), items_text TEXT NOT NULL, items_total NUMERIC(14,2) NOT NULL, delivery_fee NUMERIC(14,2) NOT NULL DEFAULT 0, total NUMERIC(14,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX idx_snack_orders_company_date ON snack_orders(company_id,created_at DESC);
